 return <><PageHeading title="My Companies" label="OPERATING PORTFOLIO · SEPARATE COMPANY ACCOUNTS"/><div className="workspace-tabs"><button onClick={()=>go('Company Marketplace')}>Company Marketplace ↗</button><button onClick={()=>go('Corporate Structure')}>Ownership hierarchy ↗</button><button onClick={()=>go('Public Companies')}>Public shareholdings ↗</button></div><Panel title="Public investment history"><div className="padded">{market.filter((r:RecordData)=>r.public&&!r.controlled).map((r:RecordData)=><p key={r.id}>{r.name} · {r.symbol} · {r.classification} · {num(r.voting_percent).toFixed(2)}% voting rights · realised {gbp(r.holding_realised)} before fees <button onClick={()=>{setSymbol(r.symbol);go('Public Companies')}}>Shareholder profile ↗</button><button onClick={()=>{setAcct(r.controller||actualAcct);setSymbol(r.symbol);go('Trading')}}>Buy / sell remaining shares ↗</button></p>)}{!(w.public_companies||[]).some((r:RecordData)=>r.controlled)&&<p>No listed issuer is under reconciled majority voting control.</p>}</div></Panel><Panel title="Controlled operating companies"><div className="inline-form"><input aria-label="Search owned companies" value={query} onChange={e=>Q(e.target.value)} placeholder="Search company, sector or country"/><select aria-label="Ownership scope" value={scope} onChange={e=>Scope(e.target.value)}><option value="all">All controlled companies</option><option value="direct">Directly owned by selected account</option></select><select aria-label="Owned company sector" value={sector} onChange={e=>Sector(e.target.value)}><option value="">All sectors</option>{Array.from(new Set(market.filter(r=>r.controlled).map(r=>r.sector))).map(s=><option key={s}>{s}</option>)}</select><select aria-label="Owned company sort" value={sort} onChange={e=>Sort(e.target.value)}><option value="name">Name ↑</option><option value="equity_value">Valuation ↓</option><option value="annual_revenue">Forecast annual revenue ↓</option><option value="employees">Workforce ↓</option></select><button disabled={pageNo===0} onClick={()=>PageNo(Math.max(0,pageNo-1))}>Previous</button><span>{rows.length} companies</span><button disabled={(pageNo+1)*20>=rows.length} onClick={()=>PageNo(pageNo+1)}>Next</button></div><div className="table-wrap"><table><thead><tr><th>Company / sector</th><th>Direct shareholder</th><th>Valuation / cash</th><th>Employees / strategy</th><th></th></tr></thead><tbody>{rows.slice(Math.min(pageNo,Math.max(0,Math.ceil(rows.length/20)-1))*20,(Math.min(pageNo,Math.max(0,Math.ceil(rows.length/20)-1))+1)*20).map(r=><tr key={r.id}><td>{r.name}<small>{r.sector} · {r.location}</small></td><td>{Object.entries(r.owners).map(([id,q])=><small key={id}>{accountName(id)} · {pct(num(q)/num(r.units))}</small>)}</td><td>{gbp(r.equity_value)}<small>{gbp(r.cash)} cash · {gbp(r.liabilities)} liabilities</small></td><td>{r.employees}<small>{r.strategy} · management {r.public?'named executives via Employees':r.management_quality+'/100'}</small></td><td><button onClick={()=>{S(r.id);T('Overview')}}>Manage company</button></td></tr>)}</tbody></table></div>{!rows.length&&<Empty>No controlled operating companies in this scope. Acquisitions appear here after settlement confers control.</Empty>}</Panel></>;
